<?php require '../../includes/config.php';require '../../includes/layout.php';require_login(['department']);$dept=$_SESSION['user']['department_id'];if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$id=(int)$_POST['ticket_id'];if(isset($_POST['status'])){$status=$_POST['status'];$allowed=['In Progress','Resolved','Closed'];if(in_array($status,$allowed,true)){if($status==='Resolved'&&isset($_POST['resolution'])){$resolution=trim($_POST['resolution']);$stmt=$conn->prepare('UPDATE tickets SET status=?,resolution=? WHERE id=? AND department_id=?');$stmt->bind_param('ssii',$status,$resolution,$id,$dept);$stmt->execute();}else{$stmt=$conn->prepare('UPDATE tickets SET status=? WHERE id=? AND department_id=?');$stmt->bind_param('sii',$status,$id,$dept);$stmt->execute();}}}if(!empty(trim($_POST['message']??''))){$text=trim($_POST['message']);$uid=$_SESSION['user']['id'];$stmt=$conn->prepare('INSERT INTO ticket_updates(ticket_id,user_id,message) VALUES(?,?,?)');$stmt->bind_param('iis',$id,$uid,$text);$stmt->execute();}$success='Case updated.';}$stmt=$conn->prepare('SELECT t.*,u.full_name,u.email,u.matric_number FROM tickets t JOIN users u ON u.id=t.student_id WHERE t.department_id=? ORDER BY t.created_at DESC');$stmt->bind_param('i',$dept);$stmt->execute();$tickets=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);dept_shell('Department Cases','dashboard');?><div class="page-header"><h2>Department Cases</h2></div><?php if(!empty($success))echo'<div class="alert alert-success">'.e($success).'</div>';?><div class="content-card table-wrap"><table><thead><tr><th>Reference</th><th>Student</th><th>Complaint</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($tickets as $t){echo'<tr><td><b>'.e($t['ref_number']).'</b><br><small>'.e(date('d M Y',strtotime($t['created_at']))).'</small></td><td>'.e($t['full_name']).'<br><small>'.e($t['matric_number']).'</small></td><td><b>'.e($t['subject']).'</b><p>'.e(substr($t['description'],0,100)).'</p></td><td>'.e($t['status']).'</td><td><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="ticket_id" value="'.(int)$t['id'].'"><select name="status"><option '.($t['status']==='In Progress'?'selected':'').'>In Progress</option><option>Resolved</option><option>Closed</option></select><textarea name="resolution" rows="2" placeholder="Resolution note (required when resolved)"></textarea><textarea name="message" rows="2" placeholder="Add case update"></textarea><button class="btn btn-primary" style="padding:7px 10px">Update</button></form></td></tr>'; }if(!$tickets)echo'<tr><td colspan="5">No cases have been routed to this department.</td></tr>';?></tbody></table></div><?php dashboard_footer(); ?>